def check_equation(x, y, z):
    return x**3 + y**3 + z**3 == x**2 * y**2 * z**2

solutions = []
# Iterate over z up to 10
for z in range(1, 11):
    # Iterate over y such that x <= y <= z
    for y in range(1, z + 1):
        # Iterate over x such that 1 <= x <= y
        for x in range(1, y + 1):
            if check_equation(x, y, z):
                solutions.append((x, y, z))

print("Solutions found (z <= 10):")
for sol in solutions:
    print(sol)

# Also print the count for verification
print(f"Total solutions found: {len(solutions)}")
